fn shell_backblaze_client() -> &'static str {
    r####"""
    const state = { bucket: null, data: null, ledger: [] };
    let statusPollTimer = null;
    const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const el = s => document.querySelector(s);
    const admitted = () => typeof viewportFamilyAdmitted === 'function' && viewportFamilyAdmitted('backblaze');
    const health = b => b?.status?.running ? 'RUNNING' : (b?.status?.last_run_ok === true ? 'GOOD' : (b?.status?.last_run_ok === false ? 'FAILED' : 'IDLE'));
    function setView(view) { document.querySelectorAll('[data-backblaze-view]').forEach(b => { const on=b.dataset.backblazeView===view; b.classList.toggle('is-active',on); b.setAttribute('aria-selected',on); }); document.querySelectorAll('[data-backblaze-panel]').forEach(p => p.hidden=p.dataset.backblazePanel!==view); if (view === 'ledger') void loadSnapshots(); }
    function setDetail(view) { document.querySelectorAll('[data-backblaze-detail]').forEach(b => { const on=b.dataset.backblazeDetail===view; b.classList.toggle('is-active',on); b.setAttribute('aria-selected',on); }); document.querySelectorAll('[data-backblaze-detail-panel]').forEach(p => p.hidden=p.dataset.backblazeDetailPanel!==view); }
    function renderLedger() { const host=el('[data-backblaze-ledger]'); if (host) host.innerHTML=state.ledger.length ? state.ledger.map(x=>`<div class="backblaze-ledger-row"><strong>${esc(x.bucket||'Backblaze')}</strong> ${esc(x.time||x.status||'Snapshot')} · ${esc(x.id||'—')}</div>`).join('') : '<p class="backblaze-empty">No restic snapshots available.</p>'; }
    function renderBuckets() { const host=el('[data-backblaze-buckets]'); if(!host)return; host.replaceChildren(); const buckets=Array.isArray(state.data?.buckets)?state.data.buckets:[]; if(!buckets.length){host.innerHTML='<p class="backblaze-empty">No buckets configured.</p>'; return;} buckets.forEach(b=>{const row=document.createElement('div');row.className='backblaze-bucket-row';row.dataset.bucket=b.bucket;const select=document.createElement('button');select.type='button';select.className='backblaze-bucket-select';select.setAttribute('aria-pressed',String(state.bucket===b.bucket));select.innerHTML=`<span>${esc(b.bucket)}</span><span class="ui-badge">${health(b)}</span>`;select.onclick=()=>selectBucket(b.bucket);const remove=document.createElement('button');remove.type='button';remove.className='backblaze-bucket-remove';remove.textContent='×';remove.title=`Remove ${b.bucket}`;remove.onclick=()=>removeBucket(b.bucket);row.append(select,remove);host.append(row);});}
    function renderSelected() { const b=state.data?.buckets?.find(x=>x.bucket===state.bucket); const title=el('[data-backblaze-selected]'); const save=el('[data-backblaze-save]'); if(!b){if(title)title.textContent='Select a bucket';if(save)save.disabled=true;return;} title.textContent=b.bucket; el('[data-backblaze-bucket-status]').textContent=`${b.prefix||'(root)'} · ${health(b)}`; el('[data-backblaze-bucket-name]').value=b.bucket; el('[data-backblaze-prefix]').value=b.prefix||''; const enc=el('[data-backblaze-encrypted]');enc.checked=b.encrypted===true;enc.disabled=false; const path=el('[data-backblaze-path]'), add=el('[data-backblaze-item-add]');path.disabled=false;add.disabled=false;if(save)save.disabled=false; const host=el('[data-backblaze-items]');host.replaceChildren();const items=Array.isArray(b.items)?b.items:[];if(!items.length)host.innerHTML='<p class="backblaze-empty">No files configured.</p>';items.forEach(i=>{const row=document.createElement('div');row.className='backblaze-path-row';row.innerHTML=`<span>${esc(i.path)}</span><button type="button" class="backblaze-path-remove" data-path="${esc(i.path)}">×</button>`;row.querySelector('button').onclick=()=>mutateItem(i.path,'DELETE');host.append(row);});}
    function selectBucket(bucket){state.bucket=bucket;renderBuckets();renderSelected();const run=el('[data-backblaze-run]');if(run)run.disabled=!bucket;}
    async function getJson(url, init){const r=await fetch(url,{...init,cache:'no-store'});return r.json().catch(()=>({ok:false,reason:'Invalid response'}));}
    async function loadSnapshots(){if(!admitted())return;const snaps=await getJson('/api/backblaze/snapshots'+(state.bucket?'?bucket='+encodeURIComponent(state.bucket):''));state.ledger=Array.isArray(snaps?.snapshots)?snaps.snapshots:[];renderLedger();}
    function clearStatusPoll(){if(statusPollTimer!==null){window.clearTimeout(statusPollTimer);statusPollTimer=null;}}
    function scheduleStatusPoll(){clearStatusPoll();if(!state.data?.running||!admitted())return;statusPollTimer=window.setTimeout(()=>{statusPollTimer=null;if(admitted())void hydrate();else clearStatusPoll();},5000);}
    async function hydrate(){if(!admitted()){clearStatusPoll();return;}try{const data=await getJson('/api/backblaze/status');state.data=data;const buckets=data?.buckets||[];if(!state.bucket && buckets.length)state.bucket=buckets[0].bucket;const overall=data?.running?'RUNNING':(data?.last_run_ok===true?'GOOD':(data?.last_run_ok===false?'FAILED':'IDLE'));el('[data-backblaze-state]').textContent=overall;el('[data-backblaze-last]').textContent=data?.last_run_at?new Date(data.last_run_at*1000).toLocaleString():'Never';el('[data-backblaze-duration]').textContent='duration unavailable';el('[data-backblaze-next]').textContent='Not scheduled';renderBuckets();renderSelected();scheduleStatusPoll();}catch(_){el('[data-backblaze-state]').textContent='FAILED';clearStatusPoll();}}
    function hydrateBackblaze(){return hydrate();}
    function secretInput(label){return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='backblaze-secret-dialog';wrap.innerHTML=`<div class="backblaze-secret-card"><label>${esc(label)}<input type="password" autocomplete="new-password"></label><div><button type="button" data-cancel>Cancel</button><button type="button" data-submit>Continue</button></div></div>`;document.body.append(wrap);const input=wrap.querySelector('input');input.focus();wrap.querySelector('[data-cancel]').onclick=()=>{wrap.remove();resolve('');};wrap.querySelector('[data-submit]').onclick=()=>{const value=input.value;input.value='';wrap.remove();resolve(value);};});}
    async function addBucket(){const bucket=prompt('B2 bucket name');if(!bucket)return;const prefix=prompt('Prefix (optional)','')||'';const keyId=prompt('B2 key ID');if(!keyId)return;const applicationKey=await secretInput('B2 application key');if(!applicationKey)return;const body=await getJson('/api/backblaze/buckets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bucket,prefix,encrypted:true,items:[],keyId,applicationKey})});el('[data-backblaze-result]').textContent=body.ok===false?(body.reason||'Bucket could not be added'):'Bucket added and verified';await hydrate();}
    async function removeBucket(bucket){if(!confirm(`Remove ${bucket}?`))return;await getJson('/api/backblaze/buckets/'+encodeURIComponent(bucket),{method:'DELETE'});if(state.bucket===bucket)state.bucket=null;await hydrate();}
    async function mutateItem(path,method){if(!state.bucket)return;await getJson('/api/backblaze/buckets/'+encodeURIComponent(state.bucket)+'/items',{method,headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});await hydrate();}
    async function saveConfig(){const b=state.data?.buckets?.find(x=>x.bucket===state.bucket);if(!b)return;const editedPrefix=el('[data-backblaze-prefix]').value.trim().replace(/^\/+|\/+$/g,'');const body=await getJson('/api/backblaze/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({buckets:state.data.buckets.map(({bucket,prefix,encrypted,items})=>({bucket,prefix:bucket===state.bucket?editedPrefix:prefix,encrypted,items}))})});el('[data-backblaze-result]').textContent=body.ok?'Config saved without credentials':(body.reason||'Config could not be saved');if(body.ok)await hydrate();}
    document.body.addEventListener('click',e=>{const v=e.target.closest('[data-backblaze-view]');if(v)setView(v.dataset.backblazeView);const d=e.target.closest('[data-backblaze-detail]');if(d)setDetail(d.dataset.backblazeDetail);if(e.target.closest('[data-backblaze-add]'))void addBucket();if(e.target.closest('[data-backblaze-save]'))void saveConfig();if(e.target.closest('[data-backblaze-item-add]')){const p=el('[data-backblaze-path]').value.trim();if(p)void mutateItem(p,'POST');}if(e.target.closest('[data-backblaze-run]')&&state.bucket)getJson('/api/backblaze/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bucket:state.bucket})}).then(hydrate);});
    document.body.addEventListener('change',e=>{if(e.target.matches('[data-backblaze-encrypted]')&&state.bucket)getJson('/api/backblaze/buckets/'+encodeURIComponent(state.bucket)+'/toggle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({encrypted:e.target.checked})}).then(hydrate);});
    setView('buckets');setDetail('config');if (typeof viewportFamilyAdmitted === 'function') void hydrate();
"####
}
